public class RMarketMethod_Bybit_QueryApi extends RMarketMethod
{
    protected RMarketJson_Bybit_QueryApi responseContract;

}

Method.Source:
public void new()
{
    apiClient = new RMarketApiClientBybit();
    apiClient.parmHttpMethod(RMarketAPIHttpMethod::GET);
    apiClient.parmMethodUrl('/v5/user/query-api');
}

public void processResponse()
{
    RMarketAPIMethodLog logRecord;

    // Do not persist the API key returned in response JSON.
    logRecord = apiClient.parmLogRecord();
    logRecord.Response = '[Redacted]';
    apiClient.parmLogRecord(logRecord);

    super();

    if (apiClient.getHttpStatus() != System.Net.HttpStatusCode::OK)
    {
        throw error(strFmt(
            "Bybit Query API: HTTP %1",
            apiClient.getHttpStatus()));
    }

    responseContract =
        RMarketJsonSerializer::deserializeObjectStrict(
            classNum(RMarketJson_Bybit_QueryApi),
            apiClient.getResponseBody())
                as RMarketJson_Bybit_QueryApi;

    if (!responseContract)
        throw error("Invalid Bybit Query API response.");

    if (!responseContract.isSuccess())
        throw error(responseContract.getErrorDetails());

    if (!responseContract.parmResult())
        throw error("Bybit Query API result is missing.");
}
